head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/list_common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");
scwin.vScrenID = "ULDFIS00100_P3.gfm";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};

/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_EntprGrpList.removeAll();
    txb_TotCnt.setValue("");
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.
    if ($c.stf.getObjectValue(txb_EntprGrpNm) == "") {
        alert("기업집단명을 입력하세요.");
        txb_EntprGrpNm.focus();
        return false;
    }
    return true;
};


/**
 * 기업목록 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_EntprGrpList);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.entprGrpList_p" + "&outputMessageId=FIS_ENTPR_GRP_LIST_P" + "&param01=" + $c.stf.getObjectValue(txb_EntprGrpNm);
    dts_EntprGrpList.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_EntprGrpList.Reset();
};


/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.fn_SetParam = function(v_Currow) {
    if (v_Currow == undefined) {
        v_Currow = dts_EntprGrpList.getRowPosition();
    }
    var arrPar = new Array();
    arrPar[0] = {
        ENTPR_GRP_CD: dts_EntprGrpList.getCellData(v_Currow, "ENTPR_GRP_CD"), //기업집단코드	
        ENTPR_GRP_NM: dts_EntprGrpList.getCellData(v_Currow, "ENTPR_GRP_NM") //기업집단명
    };

	//----W-Craft WebSquare 변환 확인: fn_SetParAffCoCd----//
    opener.fn_SetParAffCoCd(arrPar);
    scwin.fn_CloseFrame();
};


/**
 * close frame
 */
scwin.fn_CloseFrame = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_EntprGrpList_OnLoadError = function() {
    $c.stf.alert_error(dts_EntprGrpList);
};
scwin.dts_EntprGrpList_OnLoadCompleted = function(rowcount) {
    // 데이터셋 OnLoadCompleted
    if (dts_EntprGrpList.errorMsg) {
        alert(dts_EntprGrpList.errorMsg);
    } else {
        txb_TotCnt.setValue("총 " + rowcount + " 건");
    }
    $c.cm.CloseWin(rowcount, grd_EntprGrpList);
};
scwin.grd_EntprGrpList_OnDblClick = function(row, colid) {
    // 그리드 더블클릭
    scwin.fn_SetParam(row);
};
scwin.gform_onload = function() {
    // form onload
    $c.libRoundPanel.PanelToGroupBox(panel_Top); // 패널라운드 처리	


	//----W-Craft WebSquare 변환 확인: fn_GetParAffCoCd----//
    var arrPar = opener.fn_GetParAffCoCd();
    txb_EntprGrpNm.setValue(arrPar[0]);
    if (txb_EntprGrpNm.getValue() != "") {
        scwin.fn_Search();
    } else {
        txb_EntprGrpNm.focus();
    }
};
scwin.img_Close_onclick = function() {
    // 닫기버튼 클릭
    scwin.fn_CloseFrame();
};
scwin.img_Confirm_onclick = function() {
    // 확인버튼 클릭
    scwin.fn_SetParam();
};
scwin.txb_EntprGrpNm_onkeydown = function() {
    // 기업집단명 엔터
    if (event.keyCode == 13) {
        scwin.fn_Search();
    }
};
scwin.btn_Search_onclick = function() {
    // 조회 버튼 클릭
    scwin.fn_Search();
};
